"""Assemble the final evidence appendix without replacing earlier results."""
import json,statistics
from pathlib import Path
import numpy as np
from gpt_jump_report import summary
from gpt_jump_recover import legal
ROOT=Path(__file__).resolve().parent.parent
R1=ROOT/'out/competitor_20260927';R2=ROOT/'out/competitor_jump_round2';OUT=ROOT/'out/competitor_jump_round3'
def read(p):return json.loads(p.read_text())
def f(x):return '—' if x is None else f'{x:.4f}'
def main():
    arena=read(OUT/'arena_summary.json');promotions=read(OUT/'promotions.json');validation={'original':summary([r['metrics'] for r in read(OUT/'original_pinned_validate.json')])};failures={}
    for v in ['pure','tcn']:
        rows=read(OUT/f'{v}_validate.json')
        for kind in sorted({r['kind'] for r in rows}):
            ms=[r['metrics'] for r in rows if r['kind']==kind];validation[v+'_'+kind]=summary(ms)
            failures[v+'_'+kind]={k:sum(bool(m[k]) for m in ms) for k in ['fallen','foul','inverted']}
    long=read(OUT/'endurance20.json');endurance={v:sum(legal(r['metrics']) for r in long if r['variant']==v) for v in ['pure','tcn']}
    ms=[r['metrics'] for r in read(OUT/'tcn_validate.json') if r['kind']=='candidate']
    peak=np.degrees(np.max([m['residual_peak_rad'] for m in ms],axis=0));rms=np.degrees(np.sqrt(np.mean(np.array([m['residual_rms_rad'] for m in ms])**2,axis=0)))
    evidence={'arena':arena,'validation':validation,'failure_flags_at8s':failures,'endurance20_passes_out_of8':endurance,'residual_peak_degrees':peak.tolist(),'residual_rms_degrees':rms.tolist()}
    (OUT/'summary.json').write_text(json.dumps(evidence,indent=2)+'\n')
    lines=['## Round 3: closing the original robustness gap','', '**Stability pure search.** Keep the round-2 phase-indexed residual, launch keyframes, and learned parameters fixed. Search only the delay before the balanced-crouch keyframe and its standing feedback gain. The selected delay is 0.18 s and gain is 0.6. This improves recovery by changing the explicit chunk timing and balance feedback, without further fitting the residual weights.','', '**Stability temporal residual.** Keep the round-2 causal-convolution readout and launch parameters fixed and search the same two recovery parameters. The selected delay is 0.18 s and gain is 1.0. It retains temporal feedback learned in round 2; no neural weights are retrained in this grid. Both controllers are new frozen copies under `bin/challengers/gpt-jump-stable-{pure,tcn}`.','', 'Each family receives **544 full eight-second training rollouts**: its unchanged round-2 candidate plus a 4×4 recovery grid, evaluated on 32 new starts 275101–275132. Selection ranks the number legal at eight seconds, then the number legal at three seconds, then distance minus the same impact/loading penalty. This fixed bounded grid does not adapt to validation or arena scores. Validation uses **64 new starts 276101–276164**; twenty-second checks use the first eight. These seed sets are disjoint from all earlier training, validation, and arena starts.','', '### Arena verdicts','', 'Both candidates entered all three trials before any round-3 promotion. The distance and six-second comparators are the round-2 champions; the robustness comparator is the original champion. Failed guards still score -1e9. Thus the robustness paired difference includes removal of one guard failure and must not be read as a distance gain in metres.','', '| Trial | Candidate | Valid starts | Mean legal mark, m | Paired difference | p | Verdict |','|---|---|---:|---:|---:|---:|---|']
    for r in arena['entries']:lines.append(f"| {r['trial']} | {r['variant']} | {r['passes']}/{r['n']} | {f(r['mean_valid'])} | {r['mean_diff']:+.9g} | {r['p']:.5f} | {'WIN' if r['wins'] else 'LOSE'} |")
    lines+=['', 'The temporal challenger was promoted for robustness because both beat the incumbent and it had the higher mean. Its direct advantage over pure search is **0.00259375 m, p = 0.2445**; this does not establish temporal superiority on robustness. Neither grid candidate replaces the 1.363 m distance champion or the existing six-second champion. A displayed p = 0 means 0/4,000 sampled sign flips, not an exact zero.','', '### Fresh validation and attribution','', 'A reporting audit caught a reference error in the first round-3 original-controller diagnostic: it loaded the round-2 champion and forced pure mode. Those invalid files are preserved, and this table uses a corrected 64-start replay pinned to the round-1 frozen original. This correction changes only the baseline diagnostic, not search, candidate validation, endurance, or arena evidence. Round-2 original identity was also checked and was correct. Provenance is in `original_pinned_provenance.json`.','', '| Controller | Legal at 3 s | Mean legal mark at 3 s | Legal at 8 s | Mean legal mark at 8 s | Mean peak GRF, BW | Mean peak loading, BW/s |','|---|---:|---:|---:|---:|---:|---:|']
    for key in ['original','pure_previous','pure_candidate','tcn_previous','tcn_candidate','tcn_bias_only','tcn_zero_head']:
        r=validation[key];lines.append(f"| {key} | {r['legal3']}/{r['n']} | {f(r['mark3'])} | {r['legal8']}/{r['n']} | {f(r['mark8'])} | {r['peak_bw']:.2f} | {r['loading']:.0f} |")
    lines+=['',f"Twenty-second legality is **{endurance['pure']}/8 pure and {endurance['tcn']}/8 temporal**. The 64-start eight-second check still has **{64-validation['pure_candidate']['legal8']} pure and {64-validation['tcn_candidate']['legal8']} temporal failures**. Every candidate failure is flagged `fallen`; there are no fouls or inversions. This flag includes a final pelvis below 0.5 m as well as non-foot ground contact. Passing eight twenty-second starts is finite evidence, not a balance guarantee.",'', f"Temporal outputs, hip / knee / spine / shoulder: sampled peak **{' / '.join(f'{x:.2f}' for x in peak)} degrees**; full-rollout RMS **{' / '.join(f'{x:.2f}' for x in rms)} degrees**. These are 10 Hz joint-equivalent requests before geometry conversion, chunk masks, and springs. The weights are unchanged from round 2; changed sensor trajectories alter their outputs. Removing the entire head reduces eight-second legality from 56/64 to 21/64; retaining only bias gives 41/64. These are matched ablations with the same tuned backbone. The complete controller still does not outperform pure search in fresh eight-second success count (56/64 versus 60/64).",'', '### Direct temporal-versus-pure arena comparison','', '| Trial | TCN minus pure | p | TCN wins |','|---|---:|---:|---|']
    for r in arena['tcn_vs_pure']:lines.append(f"| {r['trial']} | {r['mean_diff']:+.9g} | {r['p']:.5f} | {r['wins']} |")
    lines+=['','### New champion video','']
    for r in promotions:lines.append(f"- **{r['trial']}**, temporal, seed {r['seed']}: [twenty-second video]({r['video']}); [contact sheet]({r['sheet']}). The landing settles into a crouch, with legal posture through the end of the visible motion.")
    audit=read(OUT/'completion_audit.json');assert audit['passed']
    lines+=['','## Completion checks','', 'The final audit rechecked hashes for 682 inherited files and all round-1, round-2, and round-3 frozen manifests. Shared SDK, original controllers, task physics, bridges, and arena implementation have no unexpected changes. Original trials are byte-identical after removing the one additive trial. No commits or tracked edits were made; all promotions are local to this worktree.','', 'All matched training budgets and private seed separation checks pass. Round-2 zero-head pure and temporal traces are exactly equal in commanded contractions, measured contractions, activations, and joint positions. Nonzero temporal effects reach measured motion in both later rounds. The earlier six integration checks and 50-check compiled residual spec remain valid for the unchanged code. No new training, validation, ablation, or arena artifacts contain simulation errors or nonfinite values.','', 'All twelve round-2/3 arena verdicts were independently recomputed with the unchanged arena comparison. Every promoted binary and parameter copy matches its evaluated candidate. The three current jump champions replay their stored per-seed scores exactly; the unchanged bat and crossover champions passed their earlier replay. All three later champion videos were fully decoded at 30 fps, 800×448, and cover their complete twenty-second rollouts. Earlier videos and failures are retained in the round-1 section.','', f"Machine-readable evidence: [completion audit]({OUT/'completion_audit.json'}), [champion replay]({OUT/'recheck_final.log'}), [video audit]({OUT/'video_audit.json'}), [round-3 summary]({OUT/'summary.json'}).",'', 'The three research problems now each have two genuinely different evaluated challenger families and at least one win on an existing arena trial. The robustness win is on the original 32-start trial; the added six-second diagnostic is additional evidence. These remain local simulator results. Repeated rounds and comparisons use the arena’s unadjusted rule, so this campaign is exploratory evidence rather than a multiple-testing-adjusted statistical claim.','', '## Final learned-residual versus pure-search comparison','', '**Crossovers provide the clearest temporal benefit.** The learned candidate scores 7.52 versus pure search’s 4.68 in the arena, a +2.84 paired gain with no as-favorable result in 4,000 sampled sign flips. Fresh mean crossovers fall from 7.708 to 5.042 with bias only and to 3.792 with zero head. Control is still eventually lost, and the inherited trunk pump and paddle hands do not satisfy the broader arms-only/finger technique request.','', '**Pure search remains better for batting.** It reaches 14.7206 m/s versus temporal 13.9206 m/s on the same 18 arena pitches. The temporal ablation is almost unchanged with bias only; learned time dependence has not shown useful value here. Full measured-joint diagnostics still show the hitch. More contact speed does not mean smoother technique.','', '**Jump benefits from the explicit recovery mechanism and can benefit from temporal residuals.** Round-2 temporal distance beats pure by 0.061 m (p = 0.00375) and beats the original champion by 0.0965 m. The final stability versions both beat the original robustness champion with 32/32 legal starts, while temporal versus pure is inconclusive (p = 0.2445), and pure has fewer fresh eight-second failures. Earlier touchdown and a balanced-crouch chunk account for an essential part of the improvement. Zero-head/bias ablations show that the trained temporal head contributes to recovery, but do not support a universal advantage over pure search. Only the readout is trained; convolution filters stay fixed throughout.','']
    report=ROOT/'GPT_CHALLENGERS_20260927.md';s=report.read_text();marker='## Round 3: closing the original robustness gap'
    if marker in s:s=s[:s.index(marker)]
    s=s.replace('## Results\n','## Round 1 results\n').replace('## Final verification\n','## Round 1 verification\n')
    # A compact current-board overview precedes the chronological evidence.
    start='<!-- current-results-start -->';end='<!-- current-results-end -->'
    if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
    before=read(R1/'champions_before.json');current=audit['details']['current_champions'];all_pro=[r for folder in [R1,R2,OUT] for r in read(folder/'promotions.json')];latest={r['trial']:r for r in all_pro}
    overview=[start,'## Current result','', 'Arena wins on all three selected problems, including both original standing-jump trials. All six initial challengers and four jump refinements are retained, with failed entries reported below.','', '| Existing trial | Original valid mean (passes) | New valid mean (passes) | Promoted family | Arena p |','|---|---:|---:|---|---:|']
    for t in ['search_jump_legal','search_jump_robust_legal','bat_power','dribble_crossover_25']:
        old=[x for x in before[t]['scores'] if abs(x)<1e8];new=current[t];p=latest[t]
        overview.append(f"| {t} | {statistics.mean(old):.4f} ({len(old)}/{len(before[t]['scores'])}) | {new['mean_valid']:.4f} ({new['passes']}/{new['n']}) | {p['variant']} | {p['p']:.5f} |")
    overview+=['', 'Jump distances are metres, batting is m/s, and crossovers are counts per run. Sampled p = 0 means 0/4,000 sign flips. Guard-coded paired differences, complete matched-budget comparisons, attribution, failure modes, and videos follow. The separate six-second champion now passes 26/32 starts.','',end,'']
    pos=s.index('## Protocol');s=s[:pos]+'\n'.join(overview)+'\n'+s[pos:]
    report.write_text(s.rstrip()+'\n\n'+'\n'.join(lines));print(json.dumps(evidence,indent=2))
if __name__=='__main__':main()
